package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {

    private JsonWriter writer;

    @Before
    public void setUp() throws Exception {
        writer = new JsonWriter(new StringWriter());
    }

    @Test
    public void testValueNonNullNumber() throws IOException {
        writer.value(123);
        writer.flush();
        assertEquals("{\"123\":123}", writer.out().toString());
    }

    @Test
    public void testValueNull() throws IOException {
        writer.value(null);
        writer.flush();
        assertEquals("{\"null\":null}", writer.out().toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNegativeInfinity() throws IOException {
        writer.setLenient(false);
        writer.value(-1.0 / 0.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValuePositiveInfinity() throws IOException {
        writer.setLenient(false);
        writer.value(1.0 / 0.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNaN() throws IOException {
        writer.setLenient(false);
        writer.value(0.0 / 0.0);
    }

    @Test
    public void testValueNegativeInfinityLenient() throws IOException {
        writer.setLenient(true);
        writer.value(-1.0 / 0.0);
        writer.flush();
        assertEquals("{\"-1.0/0.0\":-Infinity}", writer.out().toString());
    }

    @Test
    public void testValuePositiveInfinityLenient() throws IOException {
        writer.setLenient(true);
        writer.value(1.0 / 0.0);
        writer.flush();
        assertEquals("{\"1.0/0.0\":Infinity}", writer.out().toString());
    }

    @Test
    public void testValueNaNLenient() throws IOException {
        writer.setLenient(true);
        writer.value(0.0 / 0.0);
        writer.flush();
        assertEquals("{\"0.0/0.0\":NaN}", writer.out().toString());
    }

    @Test
    public void testValueWithBeginObject() throws IOException {
        writer.beginObject();
        writer.name("key");
        writer.value(456);
        writer.endObject();
        writer.flush();
        assertEquals("{\"key\":456}", writer.out().toString());
    }

    @Test
    public void testValueWithBeginArray() throws IOException {
        writer.beginArray();
        writer.value(789);
        writer.endArray();
        writer.flush();
        assertEquals("[789]", writer.out().toString());
    }
}
